//! Embeds the Blender icons `IconName` names, read from the kit's own copy of Blender's SVG icons
//! (`kit/intern/kit_icons_svg.c`, generated by BUI's tools/gen_svg_icons.py), so the icons stay
//! Blender's with one source of truth. blenderui has no call that draws a kit icon yet; these are
//! drawn through its SVG decoder instead.

use std::{env, fmt::Write as _, fs, path::PathBuf};

/// `IconName` variant -> Blender icon name (`UI_icons.hh`).
const ICONS: [(&str, &str); 26] = [
    ("Close", "PANEL_CLOSE"),
    ("Ellipsis", "THREE_DOTS"),
    ("Folder", "FILE_FOLDER"),
    ("File", "FILE"),
    ("Search", "VIEWZOOM"),
    ("Settings", "PREFERENCES"),
    ("Console", "CONSOLE"),
    ("Plus", "ADD"),
    ("Minus", "REMOVE"),
    ("Check", "CHECKMARK"),
    ("ChevronDown", "DOWNARROW_HLT"),
    ("ChevronRight", "RIGHTARROW"),
    ("Window", "WINDOW"),
    ("Maximize", "FULLSCREEN_ENTER"),
    ("Minimize", "FULLSCREEN_EXIT"),
    ("Eye", "HIDE_OFF"),
    ("EyeOff", "HIDE_ON"),
    ("Outliner", "OUTLINER"),
    ("Text", "TEXT"),
    ("Image", "IMAGE_DATA"),
    ("Grid", "GRID"),
    ("Pin", "PINNED"),
    ("Unpin", "UNPINNED"),
    ("Info", "INFO"),
    ("Warning", "ERROR"),
    ("Cancel", "CANCEL"),
];

fn kit_icons() -> PathBuf {
    let root = env::var_os("BUI_SOURCE_DIR").map_or_else(
        || PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").expect("cargo sets it")).join("../.."),
        PathBuf::from,
    );
    root.join("kit/intern/kit_icons_svg.c")
}

/// The SVG of `name`: the C string pieces after `{"NAME", kind,` up to the entry's end.
fn svg_of(source: &str, name: &str) -> String {
    let head = format!("  {{\"{name}\",");
    let start = source
        .find(&head)
        .unwrap_or_else(|| panic!("Blender icon {name} is not in kit_icons_svg.c"));
    let mut svg = String::new();
    for line in source[start..].lines().skip(1) {
        let line = line.trim();
        let Some(body) = line.strip_prefix('"') else { break };
        let (piece, done) = match body.strip_suffix("\"},") {
            Some(p) => (p, true),
            None => (body.strip_suffix('"').unwrap_or(body), false),
        };
        let mut chars = piece.chars();
        while let Some(c) = chars.next() {
            if c == '\\' {
                if let Some(e) = chars.next() {
                    svg.push(e);
                }
            } else {
                svg.push(c);
            }
        }
        if done {
            break;
        }
    }
    svg
}

/// The `#`s a raw string literal of `s` needs: one more than the longest `"#..#` run in it.
fn raw_hashes(s: &str) -> usize {
    s.split('"')
        .skip(1)
        .map(|after| after.chars().take_while(|&c| c == '#').count())
        .max()
        .unwrap_or(0)
        + 1
}

fn main() {
    let path = kit_icons();
    println!("cargo:rerun-if-changed={}", path.display());
    println!("cargo:rerun-if-env-changed=BUI_SOURCE_DIR");
    let source = fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("reading {} (set BUI_SOURCE_DIR to a BUI checkout): {e}", path.display()));

    let mut out = String::from(
        "/// One of Blender's icons (its name in `UI_icons.hh` is [`IconName::blender_name`]).\n\
         #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]\npub enum IconName {\n",
    );
    for (variant, blender) in ICONS {
        writeln!(out, "    /// Blender's `{blender}`.\n    {variant},").unwrap();
    }
    out.push_str("}\n\nimpl IconName {\n    /// Every icon, in declaration order.\n");
    writeln!(out, "    pub const ALL: [Self; {}] = [", ICONS.len()).unwrap();
    for (variant, _) in ICONS {
        writeln!(out, "        Self::{variant},").unwrap();
    }
    out.push_str("    ];\n\n    /// Blender's name for it (`ICON_` dropped).\n    #[must_use]\n    pub const fn blender_name(self) -> &'static str {\n        match self {\n");
    for (variant, blender) in ICONS {
        writeln!(out, "            Self::{variant} => \"{blender}\",").unwrap();
    }
    out.push_str("        }\n    }\n\n    /// Its SVG, white on transparent, as Blender ships it.\n    pub(crate) const fn svg(self) -> &'static str {\n        match self {\n");
    for (variant, blender) in ICONS {
        let svg = svg_of(&source, blender);
        let hashes = "#".repeat(raw_hashes(&svg));
        writeln!(out, "            Self::{variant} => r{hashes}\"{svg}\"{hashes},").unwrap();
    }
    out.push_str("        }\n    }\n}\n");

    let dest = PathBuf::from(env::var_os("OUT_DIR").expect("cargo sets it")).join("icons.rs");
    fs::write(dest, out).expect("writing icons.rs");
}
